import scipy.linalg as sl
from statsmodels.tsa.stattools import adfuller
def reference(x, trim=0.15, maxlag=None, regression="c", autolag="AIC"):
    z=zo; nobs=x.shape[0]
    if autolag: lags=adfuller(x,maxlag=maxlag,regression="ct",autolag=autolag,result_object=False)[2]
    elif maxlag: lags=maxlag
    else: lags=int(12.0*np.power(nobs/100.0,1/4.0))
    tc=int(nobs*trim); cols=5 if regression=="ct" else 4
    c=1/np.sqrt(nobs); tt=np.arange(1.0,nobs+2)*np.sqrt(3)/nobs**1.5
    endog,exog=z._format_regression_data(x,nobs,c,tt,cols,lags)
    y=endog[lags:]; st=np.full(nobs-tc+1,np.inf)
    for bp in range(tc+1,nobs-tc+1):
        X=z._update_regression_exog(exog,regression,bp,nobs,c,tt,cols,lags)
        Q,R=sl.qr(np.column_stack([np.delete(X,cols-1,1),X[:,cols-1],y]),mode='economic')
        k=X.shape[1]
        st[bp]=np.sqrt(len(y)-k)*np.sign(R[k-1,k-1])*R[k-1,k]/abs(R[k,k])
    return st.min(), np.argmin(st)-1, lags
rng=np.random.default_rng(5)
for kind in ["poly","sine","nearconst","smooth"]:
  for n in [200,1000]:
    t=np.arange(n)/n
    for scale in [1e-3,1e-6,1e-8]:
        if kind=="poly": x=1+t+3*t**2+scale*rng.standard_normal(n)
        elif kind=="sine": x=np.sin(6*t)+t+scale*rng.standard_normal(n)
        elif kind=="nearconst": x=5+scale*np.cumsum(rng.standard_normal(n))
        else: x=np.cumsum(np.cumsum(rng.standard_normal(n)))*(1)+scale*rng.standard_normal(n)
        for reg in ["c","t","ct"]:
            kw=dict(regression=reg,autolag=None,trim=0.15)
            a,wa=run(zo,x,**kw); b,wb=run(zn,x,**kw)
            ref=reference(x,**kw)
            if isinstance(b[0],str) or isinstance(a[0],str): print(kind,n,scale,reg,"EXC",a,b); continue
            print(f"{kind:9s} {n} {scale:g} {reg:2s} ref={ref[0]:.10g} old_err={abs(a[0]-ref[0])/abs(ref[0]):.1e} new_err={abs(b[0]-ref[0])/abs(ref[0]):.1e} bp ref/old/new={ref[1]},{a[4]},{b[4]} w={len(wa)},{len(wb)}")
